SELECT country, CASE WHEN rating >= 4.3 THEN 'HIGH' ELSE 'LOW' END AS rating_tier, STDDEV_SAMP(rating) AS rating_stddev, ROUND(AVG(rating), 2) AS avg_rating, ROUND(SUM(rating) / NULLIF(COUNT(CASE WHEN country = 'DE' THEN 1 END), 0), 2) AS rating_per_de, MAX(rating) FILTER (WHERE city = 'London') AS london_max_rating FROM suppliers GROUP BY GROUPING SETS ((country, CASE WHEN rating >= 4.3 THEN 'HIGH' ELSE 'LOW' END), (country)) ORDER BY london_max_rating DESC NULLS LAST
